function applyCoupon(cents, coupon) {
  if (!coupon) return cents;
  if (coupon.kind === "pct") return cents - Math.round((cents * coupon.value) / 100);
  return Math.max(0, cents - coupon.value);
}
function cartTotal(lines){return lines.reduce((s,l)=>s+l.unitCents*l.qty,0);}
